//! Outlands metadata: the build list and the launcher profile.
//!
//! Outlands publishes to one Maven repository (`maven.outlands.top/releases`,
//! mirrored by a CDN) and nowhere else: no loader manifest endpoint, no
//! per-build JSON URL. Two consequences shape this module.
//!
//! * The build list is the repository's `maven-metadata.xml`. Its entries are
//!   CalVer (`2026.11.14`, with `-2` for a second build that day) and the file
//!   also carries one legacy `0.6.13-alpha+build.30` entry, so the list is
//!   filtered and sorted here rather than taken in file order.
//! * The launcher profile is `version.json` at the root of the *installer JAR*.
//!   It is self-contained — every library carries `url`, `path`, `sha1` and
//!   `size`, the vanilla client jar is named in `downloads`, and there are no
//!   install processors because the binary patches travel inside the loader jar
//!   and are applied at runtime. Nothing needs to be executed, merged or
//!   re-signed; one entry has to be read out of a ZIP.

use std::io::{Cursor, Read};

use crate::customize::Downloader;
use crate::error::MdtError;

/// The repository Outlands publishes to.
///
/// This is the address the project itself uses in the profiles it ships, so it
/// is the canonical one for this loader: no mirror rewriting is applied to it.
pub const MAVEN_BASE: &str = "https://maven.outlands.top/releases";

/// Where the build list lives, relative to [`MAVEN_BASE`].
pub const MAVEN_METADATA_PATH: &str = "top/outlands/outlands/maven-metadata.xml";

/// The launcher profile inside an installer JAR.
pub const PROFILE_ENTRY: &str = "version.json";

/// The build list, newest first.
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct OutlandsVersions {
    /// Release builds only, newest first.
    pub versions: Vec<String>,
}

impl OutlandsVersions {
    /// The newest build, which is what "install Outlands" means.
    #[must_use]
    pub fn latest(&self) -> Option<&String> {
        self.versions.first()
    }
}

/// `https://maven.outlands.top/releases/top/outlands/outlands/maven-metadata.xml`
#[must_use]
pub fn metadata_url() -> String {
    format!("{MAVEN_BASE}/{MAVEN_METADATA_PATH}")
}

/// The installer JAR for a build: the only artifact that carries `version.json`.
#[must_use]
pub fn installer_jar_url(version: &str) -> String {
    format!("{MAVEN_BASE}/top/outlands/outlands/{version}/outlands-{version}-installer.jar")
}

/// The loader JAR for a build, for callers that need it separately.
#[must_use]
pub fn loader_jar_url(version: &str) -> String {
    format!("{MAVEN_BASE}/top/outlands/outlands/{version}/outlands-{version}.jar")
}

/// Fetch and parse the build list.
pub async fn fetch_versions(downloader: &dyn Downloader) -> Result<OutlandsVersions, MdtError> {
    let text = downloader.fetch(&metadata_url()).await?;
    Ok(OutlandsVersions {
        versions: parse_versions(&text),
    })
}

/// The `<version>` elements of the repository's `maven-metadata.xml`, release
/// builds only, newest first.
///
/// A full XML parser for one flat element list would be a dependency and a
/// lifetime; the file is generated by Maven and holds nothing else of interest.
#[must_use]
pub fn parse_versions(metadata: &str) -> Vec<String> {
    let mut versions: Vec<String> = Vec::new();
    let mut rest = metadata;
    while let Some(start) = rest.find("<version>") {
        let after = &rest[start + "<version>".len()..];
        let Some(end) = after.find("</version>") else {
            break;
        };
        let version = after[..end].trim();
        if is_release_version(version) {
            versions.push(version.to_string());
        }
        rest = &after[end + "</version>".len()..];
    }
    // Newest first, so callers can take the head. `sort_by` on the key keeps the
    // ordering total: two builds on one day differ only by the `-N` suffix.
    versions.sort_by_key(|version| std::cmp::Reverse(version_key(version)));
    versions
}

/// Whether an entry is a CalVer release build (`2026.11.14`, `2026.11.02-2`).
///
/// Anything else — a `-alpha` line from before the first release, a
/// `+build.N` snapshot — is not something a user should be offered.
#[must_use]
pub fn is_release_version(version: &str) -> bool {
    let (date, suffix) = match version.split_once('-') {
        Some((date, suffix)) => (date, Some(suffix)),
        None => (version, None),
    };
    let parts: Vec<&str> = date.split('.').collect();
    if parts.len() != 3 {
        return false;
    }
    let widths = [4usize, 2, 2];
    let shaped = parts
        .iter()
        .zip(widths)
        .all(|(part, width)| part.len() == width && part.chars().all(|c| c.is_ascii_digit()));
    if !shaped {
        return false;
    }
    match suffix {
        None => true,
        Some(suffix) => !suffix.is_empty() && suffix.chars().all(|c| c.is_ascii_digit()),
    }
}

/// Sort key: date first, then the same-day build number.
///
/// `2026.11.02-2` is the *second* build of that day, so it sorts after
/// `2026.11.02` — the opposite of SemVer, which reads the suffix as a
/// pre-release.
#[must_use]
pub fn version_key(version: &str) -> (u32, u32, u32, u32) {
    let (date, suffix) = match version.split_once('-') {
        Some((date, suffix)) => (date, suffix.parse().unwrap_or(0)),
        None => (version, 0),
    };
    let mut parts = date.split('.').map(|part| part.parse().unwrap_or(0));
    (
        parts.next().unwrap_or(0),
        parts.next().unwrap_or(0),
        parts.next().unwrap_or(0),
        suffix,
    )
}

/// Read `version.json` out of an installer JAR.
///
/// The archive is small (a few megabytes) and read in memory: the entry is the
/// only thing wanted from it, and the installer program it also carries is never
/// used — there are no processors to run.
pub fn profile_from_installer(bytes: &[u8]) -> Result<String, MdtError> {
    let mut archive = zip::ZipArchive::new(Cursor::new(bytes)).map_err(|error| {
        MdtError::InvalidManifest(format!("installer jar is not a readable zip: {error}"))
    })?;
    let mut entry = archive.by_name(PROFILE_ENTRY).map_err(|error| {
        MdtError::InvalidManifest(format!("installer jar has no {PROFILE_ENTRY}: {error}"))
    })?;
    let mut text = String::new();
    entry.read_to_string(&mut text).map_err(|error| {
        MdtError::InvalidManifest(format!("{PROFILE_ENTRY} is not UTF-8: {error}"))
    })?;
    Ok(text)
}

#[cfg(test)]
mod tests {
    use super::*;

    const METADATA: &str = r#"<?xml version="1.0" encoding="UTF-8"?>
<metadata>
  <groupId>top.outlands</groupId>
  <artifactId>outlands</artifactId>
  <versioning>
    <latest>2026.11.14</latest>
    <release>2026.11.14</release>
    <versions>
      <version>0.6.13-alpha+build.30</version>
      <version>2026.10.23</version>
      <version>2026.11.02</version>
      <version>2026.11.02-2</version>
      <version>2026.11.03</version>
      <version>2026.11.14</version>
    </versions>
    <lastUpdated>20261114053520</lastUpdated>
  </versioning>
</metadata>"#;

    #[test]
    fn the_legacy_alpha_line_is_not_offered() {
        let versions = parse_versions(METADATA);
        assert!(!versions.iter().any(|v| v.contains("alpha")));
        assert_eq!(versions.len(), 5);
    }

    #[test]
    fn the_newest_build_comes_first() {
        let versions = parse_versions(METADATA);
        assert_eq!(versions[0], "2026.11.14");
        assert_eq!(versions[1], "2026.11.03");
        assert_eq!(versions.last().unwrap(), "2026.10.23");
    }

    /// A same-day second build is newer, not a pre-release.
    #[test]
    fn a_same_day_suffix_sorts_after_the_plain_build() {
        let versions = parse_versions(METADATA);
        let plain = versions.iter().position(|v| v == "2026.11.02").unwrap();
        let second = versions.iter().position(|v| v == "2026.11.02-2").unwrap();
        assert!(second < plain, "{versions:?}");
    }

    #[test]
    fn only_calver_release_builds_are_accepted() {
        assert!(is_release_version("2026.11.14"));
        assert!(is_release_version("2026.11.02-2"));
        assert!(!is_release_version("0.6.13-alpha+build.30"));
        assert!(!is_release_version("2026.11"));
        assert!(!is_release_version("2026.11.02-"));
        assert!(!is_release_version("2026.11.02-beta"));
        assert!(!is_release_version(""));
    }

    #[test]
    fn urls_point_at_the_repository_the_project_ships() {
        assert_eq!(
            metadata_url(),
            "https://maven.outlands.top/releases/top/outlands/outlands/maven-metadata.xml"
        );
        assert_eq!(
            installer_jar_url("2026.11.14"),
            "https://maven.outlands.top/releases/top/outlands/outlands/2026.11.14/outlands-2026.11.14-installer.jar"
        );
        assert_eq!(
            loader_jar_url("2026.11.14"),
            "https://maven.outlands.top/releases/top/outlands/outlands/2026.11.14/outlands-2026.11.14.jar"
        );
    }

    /// The profile is one entry in a ZIP; a JAR without it is not an installer.
    #[test]
    fn the_profile_is_read_out_of_the_installer_archive() {
        let mut buffer = Cursor::new(Vec::new());
        {
            let mut writer = zip::ZipWriter::new(&mut buffer);
            let options = zip::write::SimpleFileOptions::default()
                .compression_method(zip::CompressionMethod::Deflated);
            use std::io::Write as _;
            writer.start_file(PROFILE_ENTRY, options).unwrap();
            writer
                .write_all(br#"{"id":"1.12.2-Outlands-2026.11.14"}"#)
                .unwrap();
            writer.start_file("install_profile.json", options).unwrap();
            writer.write_all(br#"{"processors":[]}"#).unwrap();
            writer.finish().unwrap();
        }
        let text = profile_from_installer(buffer.get_ref()).expect("a profile");
        assert!(text.contains("Outlands"), "{text}");
        assert!(!text.contains("processors"));
    }

    #[test]
    fn an_archive_without_the_profile_is_an_error_not_a_panic() {
        let mut buffer = Cursor::new(Vec::new());
        {
            let mut writer = zip::ZipWriter::new(&mut buffer);
            use std::io::Write as _;
            writer
                .start_file(
                    "META-INF/MANIFEST.MF",
                    zip::write::SimpleFileOptions::default(),
                )
                .unwrap();
            writer.write_all(b"Manifest-Version: 1.0\n").unwrap();
            writer.finish().unwrap();
        }
        let error = profile_from_installer(buffer.get_ref()).unwrap_err();
        assert!(error.to_string().contains(PROFILE_ENTRY), "{error}");
        let not_a_zip = profile_from_installer(b"not a zip").unwrap_err();
        assert!(not_a_zip.to_string().contains("zip"), "{not_a_zip}");
    }
}
